<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_permission('admissions.discharge');
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$id=filter_var($_POST['admission_id']??'',FILTER_VALIDATE_INT);$diagnosis=trim((string)($_POST['diagnosis']??''));$summary=trim((string)($_POST['summary']??''));$medication=trim((string)($_POST['medication_plan']??''));$followup=trim((string)($_POST['follow_up']??''));
 if(!$id||$summary===''||strlen($diagnosis)>10000||strlen($summary)>20000||strlen($medication)>10000||strlen($followup)>10000){set_flash('danger','Add a discharge summary and keep each field within 10,000 characters.');redirect('/hospital%20management/admission/index.php');}
 try{$pdo->beginTransaction();$query=$pdo->prepare('SELECT bed_id,status FROM admissions WHERE id=:id FOR UPDATE');$query->execute(['id'=>$id]);$admission=$query->fetch();if(!$admission||$admission['status']!=='admitted')throw new RuntimeException('This admission is not active.');$bed=$pdo->prepare('SELECT id FROM beds WHERE id=:id FOR UPDATE');$bed->execute(['id'=>$admission['bed_id']]);if(!$bed->fetch())throw new RuntimeException('Assigned bed no longer exists.');$q=$pdo->prepare('INSERT INTO discharge_summaries(admission_id,written_by,diagnosis,summary,medication_plan,follow_up) VALUES(:admission,:user,:diagnosis,:summary,:medication,:followup)');$q->execute(['admission'=>$id,'user'=>current_user()['id'],'diagnosis'=>$diagnosis?:null,'summary'=>$summary,'medication'=>$medication?:null,'followup'=>$followup?:null]);$pdo->prepare("UPDATE admissions SET status='discharged',discharged_at=NOW() WHERE id=:id AND status='admitted'")->execute(['id'=>$id]);$release=$pdo->prepare("UPDATE beds SET status='available' WHERE id=:id AND status='occupied'");$release->execute(['id'=>$admission['bed_id']]);if($release->rowCount()!==1)throw new RuntimeException('Assigned bed is not marked as occupied.');record_audit('discharge','admission',(string)$id,'Discharge summary saved; bed released');notify_staff('patient_discharged','admission',(string)$id,current_user()['full_name'].' discharged a patient and released the bed.');$pdo->commit();set_flash('success','Discharge summary saved. Patient discharged and bed released.');}
 catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();set_flash('danger',$e instanceof RuntimeException?$e->getMessage():'Discharge could not be completed.');}
 redirect('/hospital%20management/admission/index.php');
}
if(!$id||$id<1){http_response_code(400);exit('A valid admission is required.');}
$query=$pdo->prepare("SELECT a.id,a.reason,p.patient_no,p.first_name,p.last_name,w.name AS ward_name,b.bed_number FROM admissions a JOIN patients p ON p.id=a.patient_id JOIN beds b ON b.id=a.bed_id JOIN wards w ON w.id=b.ward_id WHERE a.id=:id AND a.status='admitted'");$query->execute(['id'=>$id]);$admission=$query->fetch();if(!$admission){http_response_code(404);exit('Active admission not found.');}
$pageTitle='Discharge patient';require __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><h2>Discharge <?=e($admission['first_name'].' '.$admission['last_name'])?></h2><p><?=e($admission['patient_no'].' · '.$admission['ward_name'].' · Bed '.$admission['bed_number'])?></p></div><a class="btn btn-outline-secondary" href="/hospital%20management/admission/index.php">Back to admissions</a></div>
<div class="alert alert-info">Complete the clinical summary, medicine plan, and follow-up instructions before releasing the bed.</div>
<form method="post" class="content-card form-card mt-0"><?=csrf_field()?><input type="hidden" name="admission_id" value="<?=(int)$admission['id']?>"><div class="row g-3"><div class="col-12"><label class="form-label">Discharge diagnosis</label><textarea class="form-control" name="diagnosis" maxlength="10000" rows="2"></textarea></div><div class="col-12"><label class="form-label">Discharge summary <span class="text-danger">*</span></label><textarea class="form-control" name="summary" maxlength="20000" rows="5" required placeholder="Treatment provided, response, and condition at discharge"></textarea></div><div class="col-md-6"><label class="form-label">Medication plan</label><textarea class="form-control" name="medication_plan" maxlength="10000" rows="3"></textarea></div><div class="col-md-6"><label class="form-label">Follow-up plan</label><textarea class="form-control" name="follow_up" maxlength="10000" rows="3" placeholder="Follow-up appointment or return instructions"></textarea></div><div class="col-12 d-flex justify-content-end"><button class="btn btn-primary">Save summary and discharge</button></div></div></form>
<?php require __DIR__.'/../includes/footer.php';?>
